// Unwrap warnings and cancellations arrays from db-api response.
// Returns two separate item streams using output index via Set nodes.
const resp = $input.first().json;
if (!resp || !resp.success) {
  return [{ json: { _type: 'noop', message: resp?.message || 'API call failed' } }];
}
const warnings      = Array.isArray(resp.warnings_to_send)      ? resp.warnings_to_send      : [];
const cancellations = Array.isArray(resp.cancellations_to_send) ? resp.cancellations_to_send : [];
// Tag each item so downstream nodes know what to do with it
const warningItems      = warnings.map(r      => ({ json: { ...r, _type: 'warning' } }));
const cancellationItems = cancellations.map(r => ({ json: { ...r, _type: 'cancellation' } }));
// Return all items in one stream; IF nodes below split by _type
return [...warningItems, ...cancellationItems];

const r = $input.first().json;
const tenantId_w = r.tenant_id || '';
let contactEmail = 'bookings@venuedesk.co.uk';
try {
  if (tenantId_w) {
    const cfg = await $helpers.httpRequest({ method: 'GET', url: 'https://api.venuedesk.co.uk/stripe/config?tenant_id=' + tenantId_w });
    contactEmail = (cfg?.data || cfg)?.staff_notification_email || contactEmail;
  }
} catch(e) {}
const customerName = r.customer_name || 'Valued Customer';
const venueName    = r.venue_name    || 'VenueDesk';
const roomName     = r.room_name     || 'the booked space';
const balance      = parseFloat(r.balance_due || 0).toFixed(2);
const fmtDate = d => {
  if (!d) return '—';
  const dt = new Date(String(d).slice(0,10) + 'T00:00:00');
  return dt.toLocaleDateString('en-GB', { weekday:'long', day:'numeric', month:'long', year:'numeric' });
};
const eventDate = fmtDate(r.event_date);
const startTime = r.start_time ? String(r.start_time).slice(0,5) : '';
const endTime   = r.end_time   ? String(r.end_time).slice(0,5)   : '';
const timeStr   = (startTime && endTime) ? ` from ${startTime} to ${endTime}` : '';

const subject = `⚠️ Action required: Outstanding balance on your booking — ${venueName}`;
const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head>
<body style="margin:0;padding:0;background:#f8fafc;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;">
  <div style="max-width:600px;margin:0 auto;padding:32px 16px;">
    <div style="background:linear-gradient(135deg,#f59e0b 0%,#d97706 100%);border-radius:12px 12px 0 0;padding:28px 32px;text-align:center;">
      <p style="margin:0 0 4px;color:rgba(255,255,255,.8);font-size:11px;letter-spacing:2px;text-transform:uppercase;">VenueDesk · Booking System</p>
      <h1 style="margin:0 0 8px;color:#fff;font-size:20px;font-weight:700;">⚠️ Payment Reminder</h1>
      <div style="background:rgba(0,0,0,.18);border-radius:8px;padding:8px 20px;display:inline-block;">
        <span style="color:#fff;font-size:28px;font-weight:800;">£${balance}</span>
        <span style="color:rgba(255,255,255,.85);font-size:14px;font-weight:600;"> outstanding</span>
      </div>
    </div>
    <div style="background:#fff;border:1px solid #e2e8f0;border-top:none;border-radius:0 0 12px 12px;padding:32px;">
      <p style="margin:0 0 16px;color:#111827;font-size:15px;">Hi <strong>${customerName}</strong>,</p>
      <p style="margin:0 0 16px;color:#4b5563;font-size:14px;line-height:1.65;">
        Your booking at <strong>${venueName}</strong> for <strong>${roomName}</strong> on <strong>${eventDate}${timeStr}</strong> has an outstanding balance of <strong style="color:#d97706;">£${balance}</strong>.
      </p>
      <div style="background:#fef3c7;border:1px solid #fde68a;border-left:4px solid #f59e0b;border-radius:8px;padding:14px 16px;margin:20px 0;">
        <p style="margin:0;color:#92400e;font-size:13px;font-weight:700;">⏰ This booking will be automatically cancelled in 48 hours if payment is not received.</p>
        <p style="margin:8px 0 0;color:#78350f;font-size:13px;line-height:1.55;">Please contact us as soon as possible to settle the outstanding balance and secure your booking.</p>
      </div>
      <div style="text-align:center;margin:28px 0 20px;">
        <a href="mailto:${contactEmail}?subject=Payment%20for%20my%20upcoming%20booking%20at%20${encodeURIComponent(venueName)}"
           style="display:inline-block;background:#6366f1;color:#fff;text-decoration:none;padding:13px 32px;border-radius:8px;font-size:14px;font-weight:600;">
          Contact Us to Pay →
        </a>
      </div>
      <div style="border-top:1px solid #f3f4f6;padding-top:20px;margin-top:8px;">
        <p style="margin:0 0 3px;font-size:13px;color:#374151;font-weight:600;">VenueDesk Booking Team</p>
        <p style="margin:0 0 3px;font-size:12px;color:#6b7280;">📧 ${contactEmail}</p>
        <p style="margin:12px 0 0;font-size:11px;color:#9ca3af;">This is an automated reminder. Booking ID: ${r.booking_id || 'N/A'}</p>
      </div>
    </div>
  </div>
</body></html>`;

return [{ json: { email: r.customer_email, subject, html, contactEmail } }];

const r = $input.first().json;
const tenantId_c = r.tenant_id || '';
let contactEmail = 'bookings@venuedesk.co.uk';
try {
  if (tenantId_c) {
    const cfg = await $helpers.httpRequest({ method: 'GET', url: 'https://api.venuedesk.co.uk/stripe/config?tenant_id=' + tenantId_c });
    contactEmail = (cfg?.data || cfg)?.staff_notification_email || contactEmail;
  }
} catch(e) {}
const customerName = r.customer_name || 'Valued Customer';
const venueName    = r.venue_name    || 'VenueDesk';
const roomName     = r.room_name     || 'the booked space';
const balance      = parseFloat(r.balance_due || 0).toFixed(2);
const fmtDate = d => {
  if (!d) return '—';
  const dt = new Date(String(d).slice(0,10) + 'T00:00:00');
  return dt.toLocaleDateString('en-GB', { weekday:'long', day:'numeric', month:'long', year:'numeric' });
};
const eventDate = fmtDate(r.event_date);
const startTime = r.start_time ? String(r.start_time).slice(0,5) : '';
const endTime   = r.end_time   ? String(r.end_time).slice(0,5)   : '';
const timeStr   = (startTime && endTime) ? ` from ${startTime} to ${endTime}` : '';

const subject = `❌ Booking cancelled — outstanding balance not received — ${venueName}`;
const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head>
<body style="margin:0;padding:0;background:#f8fafc;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;">
  <div style="max-width:600px;margin:0 auto;padding:32px 16px;">
    <div style="background:linear-gradient(135deg,#ef4444 0%,#b91c1c 100%);border-radius:12px 12px 0 0;padding:28px 32px;text-align:center;">
      <p style="margin:0 0 4px;color:rgba(255,255,255,.8);font-size:11px;letter-spacing:2px;text-transform:uppercase;">VenueDesk · Booking System</p>
      <h1 style="margin:0 0 8px;color:#fff;font-size:20px;font-weight:700;">❌ Booking Cancelled</h1>
      <p style="margin:0;color:rgba(255,255,255,.9);font-size:13px;">Outstanding balance not received</p>
    </div>
    <div style="background:#fff;border:1px solid #e2e8f0;border-top:none;border-radius:0 0 12px 12px;padding:32px;">
      <p style="margin:0 0 16px;color:#111827;font-size:15px;">Hi <strong>${customerName}</strong>,</p>
      <p style="margin:0 0 16px;color:#4b5563;font-size:14px;line-height:1.65;">
        We regret to inform you that your booking at <strong>${venueName}</strong> for <strong>${roomName}</strong> on <strong>${eventDate}${timeStr}</strong> has been <strong style="color:#ef4444;">automatically cancelled</strong> due to an unpaid balance of <strong>£${balance}</strong>.
      </p>
      <div style="background:#fee2e2;border:1px solid #fecaca;border-left:4px solid #ef4444;border-radius:8px;padding:14px 16px;margin:20px 0;">
        <p style="margin:0;color:#991b1b;font-size:13px;font-weight:700;">Your booking has been released and is no longer reserved.</p>
        <p style="margin:8px 0 0;color:#7f1d1d;font-size:13px;line-height:1.55;">If you believe this was in error or would like to rebook, please contact us as soon as possible. Availability cannot be guaranteed.</p>
      </div>
      <div style="text-align:center;margin:28px 0 20px;">
        <a href="mailto:${contactEmail}?subject=Re%3A%20Cancelled%20booking%20at%20${encodeURIComponent(venueName)}"
           style="display:inline-block;background:#6366f1;color:#fff;text-decoration:none;padding:13px 32px;border-radius:8px;font-size:14px;font-weight:600;">
          Contact Us →
        </a>
      </div>
      <div style="border-top:1px solid #f3f4f6;padding-top:20px;margin-top:8px;">
        <p style="margin:0 0 3px;font-size:13px;color:#374151;font-weight:600;">VenueDesk Booking Team</p>
        <p style="margin:0 0 3px;font-size:12px;color:#6b7280;">📧 ${contactEmail}</p>
        <p style="margin:12px 0 0;font-size:11px;color:#9ca3af;">This is an automated notification. Booking ID: ${r.booking_id || 'N/A'}</p>
      </div>
    </div>
  </div>
</body></html>`;

return [{ json: { email: r.customer_email, subject, html, contactEmail } }];
